INSERT INTO site_pages (page_key, content, seo_title, seo_description) VALUES ('home', '{"hero_kicker":"Kişiye özel fizyoterapi yaklaşımı","hero_title":"Hareketinize güven,","hero_accent":"yaşamınıza güç","hero_suffix":"katın.","hero_description":"İhtiyaçlarınızı dinleyen, hareket kapasitenizi destekleyen ve süreci sizinle birlikte şekillendiren bilimsel bir yaklaşım.","hero_image":"/furkan-toplu-hero-3d-v3.png","hero_image_alt":"Kollarını bağlayarak gülümseyen Fizyoterapist Furkan Toplu","hero_note_title":"Her hareket bir başlangıçtır.","hero_note_text":"Sizin için doğru olan yerden başlayalım.","location":"İstanbul","location_note":"Yüz yüze görüşme","fact_1":"Kişiye özel değerlendirme","fact_2":"Bilimsel ve güncel yaklaşım","fact_3":"Şeffaf süreç takibi","practice_title":"Hareketin farklı ihtiyaçlarına","practice_accent":"bütüncül bir bakış.","practice_intro":"Her süreç dinlemekle başlar. Değerlendirme sonrasında ihtiyaçlara uygun, anlaşılır ve takip edilebilir bir yol haritası oluşturulur.","practice_note":"Buradaki içerikler genel bilgilendirme amaçlıdır; kişisel değerlendirme yerine geçmez.","about_image":"/about-physiotherapist-v1.png","about_image_alt":"Klinikte duran fizyoterapist portresi","about_title":"Hareketin her insanda","about_accent":"farklı bir hikâyesi var.","about_lead":"Her bireyin ihtiyaçlarının, günlük yaşamının ve hedeflerinin farklı olduğuna inanıyorum. Bu nedenle sürece hazır kalıplarla değil, dinleyerek ve değerlendirerek başlıyorum.","about_body":"Amacım; karmaşık görünen süreci anlaşılır hale getirmek, hareketle ilgili hedefleri birlikte belirlemek ve her adımda açık bir iletişim kurmak.","value_1":"Dinlemek","value_2":"Anlamak","value_3":"Birlikte ilerlemek","approach_title":"Sade, anlaşılır ve takip edilebilir bir süreç.","step_1_title":"Sizi dinleyerek başlarız","step_1_text":"Beklentilerinizi, günlük yaşamınızı ve hareketle ilgili ihtiyaçlarınızı birlikte ele alırız.","step_2_title":"Yol haritasını netleştiririz","step_2_text":"Değerlendirme sonrasında anlaşılır ve kişiye özel bir süreç planı oluştururuz.","step_3_title":"Süreci birlikte izleriz","step_3_text":"İlerlemeyi düzenli olarak gözden geçirir, ihtiyaçlara göre planı yeniden şekillendiririz.","blog_title":"Hareketi anlamak için","blog_accent":"sade ve güvenilir bilgiler.","blog_intro":"Günlük yaşamda hareket sağlığını destekleyen, kolay anlaşılır ve kaynak odaklı içerikler.","blog_note":"Bilgi Köşesi içerikleri genel bilgilendirme amaçlıdır; tanı veya kişisel tedavi önerisi yerine geçmez.","contact_title":"İlk adımı birlikte","contact_accent":"sakin ve net atalım.","contact_intro":"Görüşme süreci, uygun saatler veya çalışma alanları hakkında bilgi almak için size uygun iletişim kanalını kullanabilirsiniz."}'::json, 'Fzt. Furkan Toplu | Fizyoterapist', 'İhtiyaçlarınızı dinleyen, hareket kapasitenizi destekleyen ve süreci sizinle birlikte şekillendiren bilimsel bir yaklaşım.') ON CONFLICT (page_key) DO NOTHING;
UPDATE site_pages SET seo_title = 'Fzt. Furkan Toplu | Fizyoterapist' WHERE page_key = 'home' AND seo_title = 'Ana sayfa | Fzt. Furkan Toplu';
INSERT INTO website_content_translations (collection, parent_id, language, status, content) SELECT 'site_pages', id, 'en', 'published', '{"hero_kicker":"An individual approach to physiotherapy","hero_title":"Move with confidence,","hero_accent":"bring strength","hero_suffix":"to your life.","hero_description":"An evidence-informed approach that listens to your needs, supports your movement and shapes the process together with you.","hero_image_alt":"Physiotherapist Furkan Toplu smiling with his arms crossed","hero_note_title":"Every movement is a beginning.","hero_note_text":"Let us start where it feels right for you.","location":"Istanbul","location_note":"In-person appointments","fact_1":"Individual assessment","fact_2":"Evidence-informed practice","fact_3":"Transparent progress reviews","practice_title":"Different movement needs,","practice_accent":"a holistic perspective.","practice_intro":"Every process starts with listening. Assessment leads to a clear, individual plan whose progress we can review together.","practice_note":"This content provides general information and does not replace an individual assessment.","about_image_alt":"Portrait of a physiotherapist in a clinic","about_title":"Movement tells","about_accent":"a different story for everyone.","about_lead":"Everyone has different needs, daily routines and goals. That is why I begin by listening and assessing each individual.","about_body":"My aim is to make the process understandable, agree on movement goals together and communicate clearly at every step.","value_1":"Listening","value_2":"Understanding","value_3":"Moving forward together","approach_title":"A clear process, with progress we review together.","step_1_title":"We start by listening","step_1_text":"Together, we explore your expectations, daily life and movement needs.","step_2_title":"We clarify the plan","step_2_text":"After assessment, we create a clear plan tailored to you.","step_3_title":"We review progress together","step_3_text":"We review progress regularly and adapt the plan to your needs.","blog_title":"Understanding movement through","blog_accent":"clear, reliable information.","blog_intro":"Accessible, source-based articles about movement in everyday life.","blog_note":"These articles provide general information and do not replace diagnosis or individual treatment advice.","contact_title":"Let us take the first step","contact_accent":"with clarity and confidence.","contact_intro":"Use the contact option that suits you to ask about appointments, availability or practice areas.","seo_title":"Physiotherapy | Furkan Toplu"}'::jsonb FROM site_pages WHERE page_key = 'home' ON CONFLICT (collection, parent_id, language) DO NOTHING;
INSERT INTO website_content_translations (collection, parent_id, language, status, content) SELECT 'site_pages', id, 'de', 'published', '{"hero_kicker":"Individuelle Physiotherapie","hero_title":"Vertrauen in Bewegung,","hero_accent":"Kraft für","hero_suffix":"Ihr Leben.","hero_description":"Ein wissenschaftlich fundierter Ansatz, der Ihre Bedürfnisse berücksichtigt, Ihre Bewegungsfähigkeit unterstützt und den Weg gemeinsam mit Ihnen gestaltet.","hero_image_alt":"Physiotherapeut Furkan Toplu lächelt mit verschränkten Armen","hero_note_title":"Jede Bewegung ist ein Anfang.","hero_note_text":"Beginnen wir dort, wo es für Sie passt.","location":"Istanbul","location_note":"Persönliche Termine","fact_1":"Individuelle Untersuchung","fact_2":"Wissenschaftlich fundierter Ansatz","fact_3":"Transparente Verlaufskontrolle","practice_title":"Unterschiedliche Bewegungsbedürfnisse,","practice_accent":"ein ganzheitlicher Blick.","practice_intro":"Jeder Weg beginnt mit Zuhören. Nach der Untersuchung entsteht ein verständlicher, individueller Plan mit nachvollziehbaren Schritten.","practice_note":"Diese Inhalte dienen der allgemeinen Information und ersetzen keine individuelle Untersuchung.","about_image_alt":"Porträt eines Physiotherapeuten in einer Praxis","about_title":"Bewegung erzählt bei jedem Menschen","about_accent":"eine andere Geschichte.","about_lead":"Jeder Mensch hat unterschiedliche Bedürfnisse, einen eigenen Alltag und persönliche Ziele. Deshalb beginne ich mit Zuhören und einer individuellen Untersuchung.","about_body":"Mein Ziel ist es, den Prozess verständlich zu machen, Bewegungsziele gemeinsam festzulegen und bei jedem Schritt offen zu kommunizieren.","value_1":"Zuhören","value_2":"Verstehen","value_3":"Gemeinsam weitergehen","approach_title":"Ein klarer Prozess mit nachvollziehbaren Schritten.","step_1_title":"Wir beginnen mit Zuhören","step_1_text":"Gemeinsam betrachten wir Ihre Erwartungen, Ihren Alltag und Ihre Bewegungsbedürfnisse.","step_2_title":"Wir klären den weiteren Weg","step_2_text":"Nach der Untersuchung erstellen wir einen verständlichen, individuellen Plan.","step_3_title":"Wir begleiten den Verlauf gemeinsam","step_3_text":"Wir überprüfen den Verlauf regelmäßig und passen den Plan Ihren Bedürfnissen an.","blog_title":"Bewegung verstehen durch","blog_accent":"klare, verlässliche Informationen.","blog_intro":"Verständliche, quellenbasierte Beiträge über Bewegung im Alltag.","blog_note":"Diese Beiträge dienen der allgemeinen Information und ersetzen keine Diagnose oder individuelle Behandlungsempfehlung.","contact_title":"Gehen wir den ersten Schritt","contact_accent":"gemeinsam und in Ruhe.","contact_intro":"Nutzen Sie den passenden Kontaktweg für Fragen zu Terminen, verfügbaren Zeiten oder Behandlungsbereichen.","seo_title":"Physiotherapie | Furkan Toplu"}'::jsonb FROM site_pages WHERE page_key = 'home' ON CONFLICT (collection, parent_id, language) DO NOTHING;
INSERT INTO site_pages (page_key, content, seo_title, seo_description) VALUES ('areas', '{"hero_title":"Her hareket ihtiyacına","hero_accent":"kendi bağlamında bakmak.","hero_description":"Aynı başlık altında görünen ihtiyaçlar bile her kişide farklı bir hikâyeye sahip olabilir. Süreç, dinleme ve değerlendirmeyle başlar.","hero_image":"","hero_image_alt":"Çalışma Alanları","note_title":"Sayfadaki başlıklar bir tanı listesi değil,","note_accent":"değerlendirme kapsamını anlatan genel çerçevelerdir.","note_text":"Kişisel ihtiyaçlar ve sürecin uygunluğu ancak bireysel görüşme ve değerlendirme sonrasında ele alınabilir."}'::json, 'Çalışma Alanları | Fzt. Furkan Toplu', 'Aynı başlık altında görünen ihtiyaçlar bile her kişide farklı bir hikâyeye sahip olabilir. Süreç, dinleme ve değerlendirmeyle başlar.') ON CONFLICT (page_key) DO NOTHING;
