INSERT INTO website_content_translations (collection, parent_id, language, status, content) SELECT 'site_pages', id, 'en', 'published', '{"hero_title":"Every movement need,","hero_accent":"seen in its own context.","hero_description":"Even similar needs can have a different story for each person. The process starts with listening and assessment.","hero_image_alt":"Practice areas","note_title":"These topics provide","note_accent":"an overview of assessment areas, rather than diagnoses.","note_text":"Individual needs and the suitability of the process can only be considered after a personal consultation and assessment.","seo_title":"Practice areas | Furkan Toplu"}'::jsonb FROM site_pages WHERE page_key = 'areas' ON CONFLICT (collection, parent_id, language) DO NOTHING;
